source_context:
 1: ---
 2: - name: Send small chars
 3:   ansible.builtin.command: qm sendkey 100 {{ char }}
 4:   when: (char >= 'a' and char <='z' )
 5: - name: Send num
 6:   ansible.builtin.command: qm sendkey 100 {{ char }}
 7:   when: (char >= '0' and char <='9' )
 8: - name: Send big chars
 9:   ansible.builtin.command: qm sendkey 100 shift-{{ char | lower }}
10:   when: (char >= 'A' and char <= 'Z' )

