 1: #--------------------------------------------------
 2: # Install Walkthrough Scripts
 3: #--------------------------------------------------
 4: 
 5: - name: Create directory for walkthrough scripts
 6:   file:
 7:     path: "/home/{{ system_user }}/walkthrough"
 8:     state: directory
 9:     owner: "{{ system_user }}"
10:     group: "{{ system_user }}"
11:     mode: 0755
12:   when: install
13: 
14: - name: Create directory for walkthrough scripts
15:   local_action:
16:     file path="/tmp/{{ inventory_hostname }}" state=directory mode=0755
17:   when: prep
18: 
19: - name: create templates for each host
20:   local_action:
21:     template src="{{ item.src }}" dest="/tmp/{{ inventory_hostname }}/{{ item.dest }}"
22:   with_items: 
