  1: - name: Configure bind mounts
  2:   vars:
  3:     mount_guests_yaml: |
  4:       {% for guest in guests %}
  5:       {% set guest_config = (
  6:         config.proxmox_vms |
  7:         selectattr('id', 'equalto', 'lxc/' ~ guest.lxc.id)
  8:       )[0].config %}
  9:       {% set mount_volumes = namespace(items=[]) %}
 10:       {% if guest.lxc.mount_volumes is mapping %}
 11:       {% for key, value in guest.lxc.mount_volumes.items() %}
 12:       {% set mount_volumes.items = mount_volumes.items + [
 13:         {'key': key, 'value': value}
 14:       ] %}
 15:       {% endfor %}
 16:       {% else %}
 17:       {% for value in guest.lxc.mount_volumes %}
 18:       {% set mount_volumes.items = mount_volumes.items + [
 19:         {'key': 'mp' ~ loop.index0, 'value': value}
 20:       ] %}
 21:       {% endfor %}
 22:       {% endif %}
 23:       - inventory_hostname: {{ guest.inventory_hostname }}
 24:         lxc: {{ guest.lxc }}
 25:         config: {{ guest_config | ansible.builtin.to_json }}
 26:         mount_volumes: {{ mount_volumes.items | ansible.builtin.to_json }}
 27:         configured_mount_volumes: {{
 28:           guest_config |
 29:           ansible.builtin.dict2items |
 30:           selectattr('key', 'match', '^mp[0-9]+$') |
 31:           list |
 32:           ansible.builtin.to_json
 33:         }}
 34:       {% endfor %}
 35:     mount_guests: >-
 36:       {{
 37:         mount_guests_yaml |
 38:         ansible.builtin.from_yaml |
 39:         default([], true) |
 40:         list
 41:       }}
 42:   block:
 43:     - name: Set bind mount
 44:       when: >-
 45:         item.0.config[item.1.key] | default('') != options_string
 46:       ansible.builtin.command:
 47:         argv:
 48:           - pct
 49:           - set
 50:           - "{{ item.0.lxc.id | ansible.builtin.mandatory }}"
 51:           - "-{{ item.1.key }}"
 52:           - "{{ options_string }}"
 53:       loop: >-
 54:         {{
 55:           mount_guests |
 56:           ansible.builtin.subelements('mount_volumes')
 57:         }}
 58:       loop_control:
 59:         label: >-
 60:           {{ item.0.inventory_hostname }}
 61:           id={{ item.0.lxc.id }}
 62:           {{ item.1.key }}={{ options_string }}
 63:       changed_when: true
 64:       vars:
 65:         options_yaml: |
 66:           {% for k, v in (item.1.value.options | default({})).items() %}
 67:           - {{ k }}={{ v }}
 68:           {% endfor %}
 69:         options_string: >-
 70:           {{
 71:             (
 72:               [
 73:                 item.1.value.host_path,
 74:                 'mp=' ~ item.1.value.mountpoint
 75:               ]
 76:               +
 77:               (
 78:                 [
 79:                   options_yaml | ansible.builtin.from_yaml
 80:                 ] |
 81:                 ansible.builtin.flatten |
 82:                 sort
 83:               )
 84:             ) |
 85:             join(',')
 86:           }}
 87: 
 88:     - name: Remove stale bind mount
 89:       when: >-
 90:         item.1.key not in (
 91:           item.0.mount_volumes |
 92:           map(attribute='key') |
 93:           list
 94:         )
 95:       ansible.builtin.command:
 96:         argv:
 97:           - pct
 98:           - set
 99:           - "{{ item.0.lxc.id | ansible.builtin.mandatory }}"
100:           - -delete
101:           - "{{ item.1.key }}"
102:       loop: >-
103:         {{
104:           mount_guests |
105:           ansible.builtin.subelements('configured_mount_volumes')
106:         }}
107:       loop_control:
108:         label: >-
109:           {{ item.0.inventory_hostname }}
110:           id={{ item.0.lxc.id }}
111:           {{ item.1.key }}
112:       changed_when: true

 1: - name: Cluster {{ cluster_id }} - Create directories
 2:   file:
 3:     path: "{{ item }}"
 4:     state: directory
 5:     mode: 0755 # For some reason, item.mode converts 0755 into 493 ... weird
 6:   loop:
 7:     - clusters/{{ cluster_id }}
 8: 
 9: - name: Cluster {{ cluster_id }} - Create openshift-install configuration
10:   template:
11:     src: "{{ item.src }}"
12:     dest: "{{ item.dest }}"
13:   vars:
14:     ssh_pub_key: "{{ ssh_pub_key_task.stdout }}"
15:     pull_secret: "{{ lookup('file', './files/pull_secret.txt', errors='ignore') }}"
16:   with_items:
17:     - {
18:         src: templates/install-config.yaml.j2,
19:         dest: "clusters/{{ cluster_id }}/install-config.yaml",
20:       }
21:     - {
22:         src: templates/agent-config.yaml.j2,
23:         dest: "clusters/{{ cluster_id }}/agent-config.yaml",
24:       }
25:   register: okd_installer_config_files
26: 
27: # Let's create the proper OKD installation files (ignition, manifests, ...)
28: - name: Cluster {{ cluster_id }} - Run openshift-installer
29:   when: okd_installer_config_files.changed
30:   shell: |
31:     cd clusters/{{ cluster_id }}
32:     rm -rf install-dir
33:     mkdir install-dir
34:     cp install-config.yaml agent-config.yaml install-dir/
35:     {% if ipxe.enabled %}
36:       {% set cmd = "pxe-files" %}
37:     {% else %}
38:       {% set cmd = "image" %}
39:     {% endif %}
40:     openshift-install agent create {{ cmd }} --dir=install-dir
41:   environment:
42:     PATH: "/usr/local/bin:/usr/bin:/bin"
43:   register: installer_task
44: 
45: # Make these files available on the Web server
46: - name: Cluster {{ cluster_id }} - Copy boot-artifacts to www directory
47:   when: installer_task.changed
48:   become: true
49:   shell: |
50:     rm -rf /var/www/html/{{ cluster_id }}
51:     mkdir /var/www/html/{{ cluster_id }}
52:     {% if ipxe.enabled %}
53:     cp -R clusters/{{ cluster_id }}/install-dir/boot-artifacts/* /var/www/html/{{ cluster_id }}
54:     {% else %}
55:     cp clusters/{{ cluster_id }}/install-dir/agent.x86_64.iso /var/www/html/{{ cluster_id }}/
56:     {% endif %}
57:     chmod -R 755 /var/www/html/{{ cluster_id }}

