  3: # AWS S3 bucket (if 'cloud_backup_provider=aws')
  4: - name: "Set variable 'pgbackrest_conf' for backup in AWS S3 bucket"
  5:   ansible.builtin.set_fact:
  6:     pgbackrest_conf:
  7:       global:
  8:         - { option: "log-level-file", value: "detail" }
  9:         - { option: "log-path", value: "/var/log/pgbackrest" }
 10:         - { option: "repo1-type", value: "s3" }
 11:         - { option: "repo1-path", value: "{{ pgbackrest_repo_path | default('/pgbackrest') }}" }
 12:         - { option: "repo1-s3-key", value: "{{ pgbackrest_s3_key | default(lookup('ansible.builtin.env', 'AWS_ACCESS_KEY_ID')) }}" }
 13:         - { option: "repo1-s3-key-secret", value: "{{ pgbackrest_s3_key_secret | default(lookup('ansible.builtin.env', 'AWS_SECRET_ACCESS_KEY')) }}" }
 14:         - { option: "repo1-s3-bucket", value: "{{ pgbackrest_s3_bucket | default(aws_s3_bucket_name | default(patroni_cluster_name + '-backup')) }}" }
 15:         - {
 16:             option: "repo1-s3-endpoint",
 17:             value: "{{ pgbackrest_s3_endpoint | default('s3.' + (aws_s3_bucket_region | default(server_location)) + '.amazonaws.com') }}",
 18:           }
 19:         - { option: "repo1-s3-region", value: "{{ pgbackrest_s3_region | default(aws_s3_bucket_region | default(server_location)) }}" }
 20:         - { option: "repo1-retention-full", value: "{{ pgbackrest_retention_full | default('30') }}" }
 21:         - { option: "repo1-retention-full-type", value: "{{ pgbackrest_retention_full_type | default('time') }}" }
 22:         - { option: "repo1-bundle", value: "y" }
 23:         - { option: "repo1-block", value: "y" }
 24:         - { option: "start-fast", value: "y" }
 25:         - { option: "link-all", value: "y" }
 26:         - { option: "resume", value: "n" }
 27:         - { option: "archive-async", value: "y" }
 28:         - { option: "archive-get-queue-max", value: "1GiB" }
 29:         - { option: "spool-path", value: "/var/spool/pgbackrest" }
 30:         - { option: "process-max", value: "{{ pgbackrest_process_max | default([ansible_processor_vcpus | int // 2, 1] | max) }}" }
 31:         - { option: "backup-standby", value: "{{ 'y' if groups['postgres_cluster'] | length > 1 else 'n' }}" }
 32:       stanza:
 33:         - { option: "log-level-console", value: "info" }
 34:         - { option: "pg1-path", value: "{{ postgresql_data_dir }}" }
