 2: 
 3: # This playbook is used with ansible-pull
 4: #
 5: - hosts: compute
 6:   remote_user: root
 7: 
 8:   # Before the roles
 9:   pre_tasks:
10:     - name: with setup module grab ansible_facts because printing ansible_facts stack traces see ansible github issue 7732
11:       setup:
12:       register: reg_pull_facts
13: 
14:     - name: debug print reg_pull_facts
15:       debug: var=reg_pull_facts
16:       
17:     - name: fetch pull_variables.yml file from pull_install_ip
18:       get_url: url="http://{{ pull_install_ip }}/pull_variables.yml" dest=/root mode=0640
19:       tags: pull
20: 
21:     - name: include_vars the pull_variables.yml
22:       include_vars: /root/pull_variables.yml
23:       tags: pull
24: 
25:     - name: Install ansible
26:       yum: pkg=ansible state=installed
27: 
28:     - name: Configure a cronjob for ansible-pull
29:       cron: name='ansible-pull' user=root 
30:             job='/bin/nice /bin/bash /usr/local/bin/ansible-pull-script.sh >/var/log/ansible.log 2>&1' 
31:             minute="{{ ansible_pull_cron_minute_interval | default('0')}}" 
32:             hour="{{ ansible_pull_cron_hour_interval | default('*/2') }}"
33:             day="{{ ansible_pull_cron_day_interval | default('*') }}"
34:             month="{{ ansible_pull_cron_month_interval | default('*') }}"
35:             weekday="{{ ansible_pull_cron_weekday_interval | default('*') }}"
36:             cron_file=ansible-pull 
37:             state={{ ansible_pull_cron_state | default('present') }}
38:       tags: pull
39: 
40:   roles:
41:   - { role: watermark-release, tags: [ 'always' ]  }
42:   - { role: ansible-role-fgci-repo, tags: [ 'fgci7', 'repos' ] }
43:   - { role: ansible-role-yum, tags: [ 'yum', 'repos', 'login' ] }
