45:   - { role: network_interface, tags: [ 'network' ] }
46:   - { role: ansible-role-hosts-int, tags: [ 'hosts'] }
47:   - { role: ansible-role-chrony, tags: [ 'ntp', 'chrony' ] }
48:   - { role: ansible-role-autofs, tags: [ 'autofs' ] }
49:   - { role: ansible-role-nis, tags: [ 'nis' ] }
50:   - { role: ansible-role-adauth, tags: [ 'auth' ] }
51:   - { role: ansible-role-pam, tags: [ 'auth', 'pam' ] }
52:   - { role: ansible-role-nsswitch, tags: [ 'nsswitch', 'auth' ] }
53:   - { role: ansible-role-yum-cron-2, tags: [ 'yumcron' ] }
54:   - { role: ansible-role-cuda, tags: [ 'cuda', 'nvidia' ] }
55:   - { role: ansible-role-rsyslog, tags: [ 'rsyslog' ] }
56:   - { role: ansible-role-aliases, tags: [ 'aliases', 'email' ] }
57:   - { role: ansible-role-postfix, tags: [ 'postfix', 'mail' ] }
58:   - { role: ansible-role-idmapd, tags: [ 'idmapd' ] }
59:   - { role: ansible-role-nfs_mount, tags: [ 'nfsmount' ] }
60:   - { role: ansible-role-sshd-host-keys, tags: [ 'sshd', 'ssh', 'host-keys' ] }
61:   - { role: ansible-role-nhc, tags: [ 'nhc', 'slurm' ] }
