  9: - name: (Deprecation) Catch and report renamed mautrix-telegram variables
 10:   ansible.builtin.fail:
 11:     msg: >-
 12:       Your configuration contains a variable, which now has a different name.
 13:       Please rename the variable (`{{ item.old }}` -> `{{ item.new }}`) on your configuration file (vars.yml).
 14:   when: "lookup('ansible.builtin.varnames', ('^' + item.old + '$'), wantlist=True) | length > 0"
 15:   with_items:
 16:     - {'old': 'matrix_bridge_mautrix_telegram_container_exposed_port_number', 'new': '<removed (the bridge no longer has a public web-based login endpoint)>'}
 17:     - {'old': 'matrix_bridge_mautrix_telegram_container_self_build', 'new': 'matrix_bridge_mautrix_telegram_container_image_self_build'}
 18:     - {'old': 'matrix_bridge_mautrix_telegram_login_shared_secret', 'new': '<removed>'}
 19:     - {'old': 'matrix_bridge_mautrix_telegram_docker_image_name_prefix', 'new': 'matrix_bridge_mautrix_telegram_container_image_registry_prefix'}
 20:     - {'old': 'matrix_bridge_mautrix_telegram_docker_repo', 'new': 'matrix_bridge_mautrix_telegram_container_image_self_build_repo'}
 21:     - {'old': 'matrix_bridge_mautrix_telegram_docker_repo_version', 'new': 'matrix_bridge_mautrix_telegram_container_image_self_build_branch'}
 22:     - {'old': 'matrix_bridge_mautrix_telegram_docker_src_files_path', 'new': 'matrix_bridge_mautrix_telegram_container_src_files_path'}
 23:     - {'old': 'matrix_bridge_mautrix_telegram_docker_image', 'new': 'matrix_bridge_mautrix_telegram_container_image'}
 24:     - {'old': 'matrix_bridge_mautrix_telegram_docker_image_force_pull', 'new': 'matrix_bridge_mautrix_telegram_container_image_force_pull'}
 25:     - {'old': 'matrix_bridge_mautrix_telegram_container_image_force_pull', 'new': '<removed> (the new community.docker.docker_image_pull module handles this natively)'}
 26:     - {'old': 'matrix_bridge_mautrix_telegram_docker_image_registry_prefix', 'new': 'matrix_bridge_mautrix_telegram_container_image_registry_prefix'}
 27:     - {'old': 'matrix_bridge_mautrix_telegram_docker_image_registry_prefix_upstream', 'new': 'matrix_bridge_mautrix_telegram_container_image_registry_prefix_upstream'}
 28:     - {'old': 'matrix_bridge_mautrix_telegram_docker_image_registry_prefix_upstream_default', 'new': 'matrix_bridge_mautrix_telegram_container_image_registry_prefix_upstream_default'}
 29:     - {'old': 'matrix_bridge_mautrix_telegram_container_repo', 'new': 'matrix_bridge_mautrix_telegram_container_image_self_build_repo'}
 30:     - {'old': 'matrix_bridge_mautrix_telegram_container_repo_version', 'new': 'matrix_bridge_mautrix_telegram_container_image_self_build_branch'}
 31:     # Variables removed in the bridgev2 (Go) rewrite — mautrix-telegram no longer has a Python runtime,
 32:     # a separate lottieconverter container or a web-based login endpoint.
 33:     # (matrix_bridge_mautrix_telegram_scheme was part of this group too, but has since been reintroduced to configure the bridge's HTTP API exposure address, so it's intentionally not listed here.)
 34:     - {'old': 'matrix_bridge_mautrix_telegram_hostname', 'new': '<removed (the bridge no longer has a public web-based login endpoint)>'}
 35:     - {'old': 'matrix_bridge_mautrix_telegram_path_prefix', 'new': '<removed (the bridge no longer has a public web-based login endpoint)>'}
 36:     - {'old': 'matrix_bridge_mautrix_telegram_public_endpoint', 'new': '<removed (the bridge no longer has a public web-based login endpoint)>'}
 37:     - {'old': 'matrix_bridge_mautrix_telegram_appservice_public_enabled', 'new': '<removed (the bridge no longer has a public web-based login endpoint)>'}
 38:     - {'old': 'matrix_bridge_mautrix_telegram_appservice_public_external', 'new': '<removed (the bridge no longer has a public web-based login endpoint)>'}
 39:     - {'old': 'matrix_bridge_mautrix_telegram_container_labels_public_endpoint_enabled', 'new': '<removed (the bridge no longer has a public web-based login endpoint)>'}
 40:     - {'old': 'matrix_bridge_mautrix_telegram_container_labels_public_endpoint_hostname', 'new': '<removed (the bridge no longer has a public web-based login endpoint)>'}
 41:     - {'old': 'matrix_bridge_mautrix_telegram_container_labels_public_endpoint_path_prefix', 'new': '<removed (the bridge no longer has a public web-based login endpoint)>'}
 42:     - {'old': 'matrix_bridge_mautrix_telegram_container_labels_public_endpoint_traefik_rule', 'new': '<removed (the bridge no longer has a public web-based login endpoint)>'}
 43:     - {'old': 'matrix_bridge_mautrix_telegram_container_labels_public_endpoint_traefik_priority', 'new': '<removed (the bridge no longer has a public web-based login endpoint)>'}
 44:     - {'old': 'matrix_bridge_mautrix_telegram_container_labels_public_endpoint_traefik_entrypoints', 'new': '<removed (the bridge no longer has a public web-based login endpoint)>'}
 45:     - {'old': 'matrix_bridge_mautrix_telegram_container_labels_public_endpoint_traefik_tls', 'new': '<removed (the bridge no longer has a public web-based login endpoint)>'}
 46:     - {'old': 'matrix_bridge_mautrix_telegram_container_labels_public_endpoint_traefik_tls_certResolver', 'new': '<removed (the bridge no longer has a public web-based login endpoint)>'}
 47:     - {'old': 'matrix_bridge_mautrix_telegram_container_http_host_bind_port', 'new': '<removed (the bridge no longer has a public web-based login endpoint)>'}
 48:     - {'old': 'matrix_bridge_mautrix_telegram_filter_mode', 'new': '<removed (not available in the bridgev2 rewrite of mautrix-telegram)>'}
 49:     - {'old': 'matrix_bridge_mautrix_telegram_bot_token', 'new': '<removed; the old-style relaybot is gone — use the common bridge relay mode (matrix_bridge_mautrix_telegram_bridge_relay_enabled) instead>'}
 50:     - {'old': 'matrix_bridge_mautrix_telegram_bridge_login_shared_secret_map', 'new': '<superseded by matrix_bridge_mautrix_telegram_double_puppet_secrets>'}
 51:     - {'old': 'matrix_bridge_mautrix_telegram_bridge_login_shared_secret_map_auto', 'new': '<superseded by matrix_bridge_mautrix_telegram_double_puppet_secrets_auto>'}
 52:     - {'old': 'matrix_bridge_mautrix_telegram_bridge_login_shared_secret_map_custom', 'new': '<superseded by matrix_bridge_mautrix_telegram_double_puppet_secrets_custom>'}
 53:     - {'old': 'matrix_bridge_mautrix_telegram_username_template', 'new': '<removed (no longer configurable via a single variable; use matrix_bridge_mautrix_telegram_configuration_extension_yaml if needed)>'}
 54:     - {'old': 'matrix_bridge_mautrix_telegram_alias_template', 'new': '<removed (room aliases are no longer created by the bridgev2 rewrite of mautrix-telegram)>'}
 55:     - {'old': 'matrix_bridge_mautrix_telegram_displayname_template', 'new': '<superseded by matrix_bridge_mautrix_telegram_network_displayname_template (note: the syntax has changed to Go templates)>'}
 56:     - {'old': 'matrix_bridge_mautrix_telegram_appservice_database', 'new': '<superseded by matrix_bridge_mautrix_telegram_appservice_database_uri>'}
 57:     - {'old': 'matrix_bridge_mautrix_telegram_lottieconverter_container_image_self_build', 'new': '<removed (lottieconverter is now bundled into the mautrix-telegram image)>'}
 58:     - {'old': 'matrix_bridge_mautrix_telegram_lottieconverter_container_image_self_build_mask_arch', 'new': '<removed (lottieconverter is now bundled into the mautrix-telegram image)>'}
