 96: - name: Fail if required mautrix-telegram settings not defined
 97:   ansible.builtin.fail:
 98:     msg: >-
 99:       You need to define a required configuration setting (`{{ item.name }}`).
100:   when: "item.when | bool and lookup('vars', item.name, default='') | string | length == 0"
101:   with_items:
102:     - {'name': 'matrix_bridge_mautrix_telegram_api_id', when: true}
103:     - {'name': 'matrix_bridge_mautrix_telegram_api_hash', when: true}
104:     - {'name': 'matrix_bridge_mautrix_telegram_appservice_token', when: true}
105:     - {'name': 'matrix_bridge_mautrix_telegram_homeserver_address', when: true}
106:     - {'name': 'matrix_bridge_mautrix_telegram_homeserver_token', when: true}
107:     - {'name': 'matrix_bridge_mautrix_telegram_container_network', when: true}
108:     - {'name': 'matrix_bridge_mautrix_telegram_database_hostname', when: "{{ matrix_bridge_mautrix_telegram_database_engine == 'postgres' }}"}
