110: # Temporary workaround for an upstream SQLite legacy-migration bug in mautrix-telegram v0.2604.0.
111: # See the separate task file for details; the whole file (and this include) can be deleted once
112: # upstream ships a release that fixes the bug.
113: - name: Guard against the upstream mautrix-telegram v0.2604.0 SQLite legacy-migration bug
114:   ansible.builtin.include_tasks: "{{ role_path }}/tasks/validate_config_sqlite_legacy_migration_bug.yml"
115:   when:
116:     - "matrix_bridge_mautrix_telegram_database_engine == 'sqlite'"
117:     - "not (matrix_bridge_mautrix_telegram_bridgev2_sqlite_upgrade_confirmed | default(false) | bool)"
118: 
119: # Bridgev2 permission values are: block, relay, commands, user, admin.
120: # The old Python bridge had different levels (relaybot, user, puppeting, full, admin).
121: # `user` and `admin` still exist in both but with different semantics (the new `user` is
122: # equivalent to the old `full`/`puppeting`). `relaybot`, `puppeting` and `full` don't exist
123: # in bridgev2 and will cause the bridge to reject its config at startup.
124: #
125: # We check the fully-merged configuration (not just `matrix_bridge_mautrix_telegram_bridge_permissions`)
126: # because users commonly override permissions via `matrix_bridge_mautrix_telegram_configuration_extension_yaml`,
127: # and those overrides would otherwise slip through validation.
128: - name: Fail if bridge permissions still reference legacy Python-bridge permission levels
129:   ansible.builtin.fail:
130:     msg: |-
131:       Your final mautrix-telegram configuration contains a `bridge.permissions` entry with
132:       value `{{ item.value }}` (for `{{ item.key }}`). This was a permission level in the legacy
133:       (Python) mautrix-telegram bridge but is not valid in the bridgev2 rewrite shipped in v0.2604.0
134:       — the bridge would reject this at startup.
135: 
136:       Valid values are: `relay`, `commands`, `user`, `admin` (plus `block`).
137: 
138:       Rough mapping from the old levels:
139: 
140:         relaybot  -> relay
141:         user      -> user (semantics changed: this now grants full puppeting, like the old `full`)
142:         puppeting -> user
143:         full      -> user
144:         admin     -> admin
145: 
146:       See https://docs.mau.fi/bridges/general/permissions.html and the bridge's example config
147:       for details. Update either `matrix_bridge_mautrix_telegram_bridge_permissions` or the `bridge.permissions`
148:       section inside `matrix_bridge_mautrix_telegram_configuration_extension_yaml` — whichever you use.
149:   when: "item.value in ['relaybot', 'puppeting', 'full']"
150:   loop: "{{ (matrix_bridge_mautrix_telegram_configuration.bridge.permissions | default({})) | dict2items }}"
151:   loop_control:
152:     label: "{{ item.key }}"

